import os,statistics
from collections import defaultdict
TERMS=['chatgpt','copilot','claude','gemini','ai-assisted','ai generated','generated by ai','llm','prompt','cursor','codeium']
def signal(text):
 t=(text or '').lower(); return min(1.0,sum(x in t for x in TERMS)*.25)
def analyze(evidence,time_entries):
 by=defaultdict(list)
 for e in evidence:
  if e.issue_key: by[e.issue_key].append(e)
 ai=[e for e in evidence if e.ai_signal>=.25]; strong=[e for e in ai if e.evidence_strength>=.75]
 avg=statistics.mean([t.hourly_cost for t in time_entries]) if time_entries else float(os.getenv('DEFAULT_HOURLY_COST','60'))
 assisted=sum(t.hours for t in time_entries if any(e.issue_key==t.issue_key and e.ai_signal>=.5 for e in by.get(t.issue_key,[])))
 low=sum(1 for issue,ev in by.items() if any('rework' in (e.text or '').lower() or 'fix generated' in (e.text or '').lower() for e in ev))
 gross=assisted*.15; saved=max(0,gross-min(gross*.6,low*.5)); cost=len(ai)*4; savings=saved*avg
 attr=min(.98,.45+.12*len(strong)+.03*len(ai)); impact=max(0,min(.95,.45+(.25 if assisted else 0)+(.15 if time_entries else 0)-.08*low)); safety=.35 if any('secret' in (e.text or '').lower() for e in ai) else .95
 return {'ai_score':round(100*(.35*attr+.35*impact+.3*safety),1),'safety_score':round(safety*100,1),'attribution_confidence':round(attr*100,1),'impact_confidence':round(impact*100,1),'estimated_hours_saved':round(saved,2),'estimated_hours_saved_low':round(saved*.55,2),'estimated_hours_saved_high':round(saved*1.35,2),'estimated_savings':round(savings,2),'ai_cost':round(cost,2),'net_benefit':round(savings-cost,2),'low_value_cases':low,'assumptions':['MVP uses a conservative 15% productivity delta for strongly attributed AI-assisted work.','Low/high range expresses model uncertainty, not a statistical confidence interval.','AI cost is an MVP proxy of €4 per corroborated AI signal.','Repository/task evidence cannot by itself prove causality.'],'recommendations':['Capture AI tool events with task IDs and timestamps.','Track review and rework separately for AI-assisted work.','Import provider billing data for measured AI cost.','Preserve comparable non-AI tasks for stronger baselines.']}
